import{_ as a,a0 as s,w as T,s as r,ao as n,I as p,x as o,a1 as t,A as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"LFCS 命令列基礎 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 命令列基礎 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 命令列基礎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 命令列基礎 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161222 LFCS Command Line Basics","title":"LFCS 命令列基礎","tag":"201701","desc":""},"relativePath":"201701/20161222 LFCS Command Line Basics.md","filePath":"[post].md"}'),i={name:"201701/20161222 LFCS Command Line Basics.md"};function l(m,e,u,C,L,g){const d=s("Link");return T(),r("div",null,[e[13]||(e[13]=n('<h1 id="lfcs-命令列基礎" tabindex="-1">LFCS 命令列基礎 <a class="header-anchor" href="#lfcs-命令列基礎" aria-label="Permalink to “LFCS 命令列基礎”">​</a></h1><p>本文中包含了很多命令列基礎。我們將討論 TeleTYpe（TTY）和幾個命令及其選項。確保做完所有練習，並要知道，除非另有説明，對 CentOS 和 Ubuntu 都是相同的。</p><h3 id="tty" tabindex="-1">TTY <a class="header-anchor" href="#tty" aria-label="Permalink to “TTY”">​</a></h3><p>當沒有圖形用户界面（GUI）或當用户在 GUI 之外，Linux 就會使用 TTY。當打開終端窗口時也使用 TTY，但這些是不同類型的 TTY。</p><p>有三種類型的 TTY：</p><ol><li>物理終端</li><li>本地偽終端</li><li>遠程偽終端</li></ol><p>基本上，每個 Linux 系統有大約六個或七個物理 TTY。 通過按住 <code>CTRL + ALT</code> 鍵，然後在 CentOS 按住 <code>F1</code> 到 <code>F6</code> ，而在 Ubuntu 中是 <code>F1</code> 到 <code>F7</code>。</p><p><strong>注意：</strong> 一些發行版可能有不同數量的 TTY 和不同的 GUI 默認位置。有點發行版可能有在物理 TTY 之間切換的不同組合鍵，如 <code>CTRL + F#</code> 或 <code>ALT + F#</code> （ LCTT 譯註：<code>F#</code> 代表 F1、F2 等）。當使用 VirtualBox 時，除非您更改了主機鍵映射，請使用右 CTRL 鍵。</p><p>在 CentOS 中，GUI 在 TTY1（<code>CTRL + ALT + F1</code>）上，其他物理 TTY 都是基於文本的。 在 Ubuntu 上，GUI 在 TTY7（<code>CTRL + ALT + F7</code>）上，其他物理 TTY 都是基於文本的。</p><p><strong>注意：</strong> 嘗試在另一個 TTY 下加載 GUI 是不明智的，因為這可能耗用大量資源，但你可以這樣做。</p><p>當 Linux 啓動時，不管是 CentOS 還是 Ubuntu，都會打開默認 TTY。如果安裝了 GUI，對於 CentOS 是打開 TTY1，對於 Ubuntu 是打開 TTY7。如果你打開一個終端窗口（偽 TTY）並使用命令 <code>who</code>，你可以看到正在使用的 TTY 的列表。 如圖 1 所示。</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.93/" alt="Figure 01.jpg"></p><p><em>圖 1</em></p><p>在圖 1 中，你可以看到我當前登錄到 TTY1（非 GUI）。第二行連接顯示我已登錄到 GUI（TTY7）以及兩個偽 TTY（PTS/1 和 PTS/2）。如圖 2，你可以看到新條目顯示了遠程偽 TTY（PTS/3）。 遠程偽連接來自 IP 地址為 192.168.0.11 的系統。</p><p><img src="https://www.linuxforum.com/attachments/figure-02-jpg.94/" alt="Figure 02.jpg"></p><p><em>圖 2</em></p><p>可以使用諸如 PuTTY 或任何 SSH 的客户端（如果遠程 Linux 系統上啓用了 SSH）之類的應用程序進行遠程 TTY 連接。</p><p>如果終端窗口字體比較小，你可以使用 <code>CTRL + SHIFT</code> 鍵和 <code>+</code> 鍵來放大字體。多次按下可以更大。要縮小大小，請使用 <code>CTRL + SHIFT + -</code> 不斷縮小。要使終端字體恢復為原始大小，請按下 <code>CTRL + SHIFT + 0</code>。</p><p><strong>注意：</strong> 請注意，如果字體已經足夠大或足夠小了，組合鍵就不再工作了。</p><p>希望你現在已經瞭解各種類型的 TTY。讓我們看看一些可以在 TTY 中使用的命令。</p><h3 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to “命令”">​</a></h3><p>其中一個命令前面已經討論過了。命令 <code>who</code> 用於顯示誰登錄到了系統。</p><p>另一個命令是 <code>pwd</code>。命令 <code>pwd</code> 代表“打印工作目錄（Print Working Directory）”。該命令返回你所在的當前目錄。例如，如果終端提示符是 <code>[jbuse@localhost〜]$</code>，則用户名為 <code>jbuse</code>，當前目錄為 <code>〜</code>。波浪號（<code>〜</code>）代表用户的主文件夾。主文件夾應該是 <code>/home/USERNAME</code>。用户名是用於登錄系統的名稱。</p><p>要列出當前文件夾的內容，請使用命令 <code>ls</code>。<code>ls</code> 命令代表 List。如果未指定任何選項，則列出當前文件夾。如果給出文件夾名稱，則會列出該文件夾的內容。例如，要查看 <code>media</code> 文件夾的內容，你可以使用命令 <code>ls /media</code>。</p><p>在 <code>ls</code> 命令後面我們可以添加一些選項以顯示更多詳細信息或特定詳細信息。如果你想看到所有的文件夾和文件，即使是隱藏的，請使用選項 <code>-a</code>。要查看當前目錄中的所有文件和文件夾，請使用命令 <code>ls -a</code>。隱藏的文件和文件夾將在名稱前面顯示一個句點（<code>.</code>）。</p><p>要在每個文件夾名稱後看到正斜槓（<code>/</code>），請使用 <code>-F</code> 選項。當前文件夾列表將是 <code>ls -F</code>。<code>-F</code> 用於按文件類型對文件進行分類。符號鏈接在文件夾名稱後用 <code>@</code> 表示。</p><p>你可以把這兩個選項連在一起形成 <code>ls -aF</code>。</p><p><strong>注意：</strong> 一些選項可能有不同的大小寫。選項區分大小寫。</p><p>另一個選項是顯示長列表的 <code>-l</code>。示例輸出如圖 3 所示。文件夾和文件名稱列在右側。文件為白色，文件夾為深藍色，符號鏈接為淺藍色。如圖 3 所示，符號鏈接 <code>vtrgb</code> 鏈接自 <code>/etc/alternatives/vtrgb</code> 。</p><p><img src="https://www.linuxforum.com/attachments/figure-03-jpg.95/" alt="Figure 03.jpg"></p><p><em>圖 3</em></p><p>左側的第一列是文件或文件夾的權限。第一個字母是 <code>d</code> 的為目錄，是 <code>-</code> 的為文件。接下來的三個字母顯示所有者的權限（<code>r</code> - 讀、<code>w</code> - 寫、<code>x</code> - 執行），後面是組權限以及“其他人”的權限。下一列數字顯示指向文件或文件夾的鏈接數。再下一列是所有者名稱，後面是所有組名稱。再下一列是文件或文件夾在存儲設備上佔用的字節數。接下來的三列是文件上次修改的月份、日期和年份。最後一列是路徑名。</p><p>目前為止，你可以看到列表是按字母順序排序。要顛倒從 “z” 到 “a” 而不是 “a” 到 “z” 的順序，請使用 <code>-r</code> 選項。逆轉選項 <code>-r</code> 使 ls 命​​令反轉輸出順序。</p><p>要按修改的時間戳列出文件，請使用 <code>-t</code> 選項。順序是從最近修改到最早的修改日期。當然，在命令 <code>ls -tr</code> 中，同時使用 <code>-t</code> 和 <code>-r</code> 顛倒了順序。</p><p>如果你不喜歡看文件的長長的字節數，使用選項 <code>-h</code>。輸出將會更易讀，如顯示 <code>4.0K</code> 而不是 <code>4096</code>。</p><p>要獲取單個文件夾的特定信息，請使用選項 <code>-d</code>，但必須指定該文件夾。例如，要查看文件夾 <code>/media</code> 的詳細信息，請使用命令 <code>ls -ld /media</code>。</p><p>另一個要熟悉的命令是命令 <code>cat</code>。命令 <code>cat</code> 用於將標準輸入（文件）複製到標準輸出（屏幕）。使用 <code>cat</code> 可以輕鬆地查看文件的內容。例如，要查看名為 <code>text</code> 的文件的內容，如果你與文件 <code>text</code> 在同一個文件夾中請使用命令 <code>cat text</code>。如果你不在同一個文件夾中，那麼你必須指定位置。例如，如果文件 <code>text</code> 在文件夾 <code>/home/jarret/test/</code> 中，那麼命令將是 <code>cat /home/jarret/test/text</code>。</p><p>另一個非常有用的命令是 <code>man</code>。<code>man</code> 命令用於查看特定命令的文檔。例如，要查看命令 <code>ls</code> 的幫助頁面，請使用命令 <code>man ls</code>。</p><p><strong>注意：</strong> 記住，在 LFCS 考試中，你可以使用 <code>man</code> 命令。</p><p>查看這些命令並測試它們以熟悉它們。使用 <code>man</code> 命令，查看本文中的命令以查看其他可用的選項。</p><hr>',41)),p("p",null,[e[1]||(e[1]=o("via: ",-1)),t(d,{href:"https://www.linuxforum.com/threads/lfcs-command-line-basics.3334/"},{default:c(()=>[...e[0]||(e[0]=[o("https://www.linuxforum.com/threads/lfcs-command-line-basics.3334/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=o("作者：",-1)),t(d,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:c(()=>[...e[2]||(e[2]=[o("Jarret",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),t(d,{href:"https://github.com/geekpi"},{default:c(()=>[...e[3]||(e[3]=[o("geekpi",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),t(d,{href:"https://github.com/wxy"},{default:c(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(d,{href:"https://github.com/LCTT/TranslateProject"},{default:c(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),t(d,{href:"https://linux.cn/"},{default:c(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const S=a(i,[["render",l]]);export{F as __pageData,S as default};
